@If (CC1 = ""; @Return(@Do(@Command([EditGotoField];"CC1") ;@Prompt([Ok];"Missing Value"; "Please select your div/dept head's email address before proceeding!")));"");

FIELD DateSent := @Today;
FIELD CurrentAction :="Reply";

@Command([FileSave]);

@SetField("RespondBy";DueDate);
@Command([FileSave]);
@Command([ViewRefreshFields]);
@If(CurrentAction="Reply";@SetField("temp";OFINo);"");

@Command([FileSave]);

@MailSend(Recipient1;FirstMail:AddEMails;NULL;"OFI Request -  " + temp + " Location: " + Location2;NULL;"Please click the doclink to open the OFI  ---> ";[IncludeDoclink]);

