@If (CPA_1 = "Rejected" & No_Reply = 2 & (Comment3 != "" | ComDate3 != ""  | Comment4 != "" | ComDate4 != "");@Return(@Do(@Command([EditGotoField];"Comment3") ;@Prompt([Ok]; "Missing Value"; "Please fill in data for Comment 1 and 2 only")));"");
@If (CPA_1 = "Rejected";@If (No_Reply = 3 & (Comment1 = "" | ComDate1 = "" | Comment2 = "" | ComDate2 = "" | Comment3 = "" | ComDate3 = "");@Return(@Do(@Command([EditGotoField];"Comment3") ;@Prompt([Ok]; "Missing Value"; "Please fill in Comment 3")));"");"");
@If (CPA_1 = "Rejected" & No_Reply = 3 & (Comment4 != "" | ComDate4 != "");@Return(@Do(@Command([EditGotoField];"Comment4") ;@Prompt([Ok]; "Missing Value"; "Please fill in data for Comment 1, 2 and 3 only")));"");
