@If ((Comment1 = "" ) | (Comment1 != "" & ComDate1 != "");""; @Return(@Do(@Command([EditGotoField];"Comment1") ;@Prompt([Ok]; "Missing Value"; "Please fill in all data for Comment 1"))));
@If ((Comment2 = "" ) | (Comment2 != "" & ComDate2 != "");""; @Return(@Do(@Command([EditGotoField];"Comment2") ;@Prompt([Ok]; "Missing Value"; "Please fill in all data for Comment 2"))));
